#!/usr/bin/env python3
import base64, gzip, json, sys
from pathlib import Path
GREEN="\033[92m"; RESET="\033[0m"; BOLD="\033[1m"
if not Path("wraith_net/modules/reporter.py").exists():
    print("Run from inside wraith-net repo"); sys.exit(1)
files = json.loads(gzip.decompress(base64.b64decode("")).decode())
for rel, content in files.items():
    Path(rel).write_text(content)
    print(f"  {GREEN}[OK]{RESET}   {rel}")
print(f"\n{BOLD}Done.{RESET} git add -A && git commit --no-gpg-sign -m \"fix: risk score calibration\" && git push")
